		.binaryTarget(name: "DevoraCoreFFI", path: "build/DevoraCoreFFI.xcframework"),
		.binaryTarget(name: "GhosttyKit", path: "build/GhosttyKit.xcframework"),

		// The UniFFI bindings for devora-ffi, generated by `mise run core`.
		.target(name: "CoreBindings", dependencies: ["DevoraCoreFFI"]),
